use atlas_sqlcipher_proof::Vault;use std::{fs,path::Path,time::{Duration,Instant},process::{Command,Stdio},thread};
fn temp()->std::path::PathBuf{let d=std::env::temp_dir().join(format!("atlas-closed-snapshot-{}",uuid::Uuid::new_v4()));fs::create_dir(&d).unwrap();d}
fn make(path:&Path){let mut v=Vault::create(path,"test-password").unwrap();v.put_note("id","title","OriginalBodyUnique48917").unwrap();drop(v)}
#[test]fn closed_snapshot_and_wrong_password(){let d=temp();let src=d.join("source");let dst=d.join("copy");make(&src);let before=fs::read(&src).unwrap();assert!(Vault::snapshot_closed(&src,&dst,"wrong-password",|_,_|{}).is_err());assert!(!dst.exists());assert_eq!(fs::read(&src).unwrap(),before);Vault::snapshot_closed(&src,&dst,"test-password",|_,_|{}).unwrap();assert_eq!(Vault::open(&dst,"test-password").unwrap().get_note("id").unwrap(),"OriginalBodyUnique48917");assert_eq!(fs::read(&src).unwrap(),before);for p in [&src,&dst]{let bytes=fs::read(p).unwrap();assert!(!bytes.windows(23).any(|x|x==b"OriginalBodyUnique48917"));}fs::remove_dir_all(d).unwrap();}
#[test]fn dirty_sqlite_sidecars_refuse_without_destination(){for suffix in ["-wal","-journal"]{let d=temp();let src=d.join("source");let dst=d.join("copy");make(&src);let sidecar=d.join(format!("source{suffix}"));fs::write(&sidecar,b"artificial nonempty sidecar").unwrap();let before=fs::read(&src).unwrap();assert!(Vault::snapshot_closed(&src,&dst,"test-password",|_,_|{}).is_err(),"accepted {suffix}");assert!(!dst.exists());assert_eq!(fs::read(&src).unwrap(),before);assert_eq!(fs::read(sidecar).unwrap(),b"artificial nonempty sidecar");fs::remove_dir_all(d).unwrap();}}
#[cfg(feature="test-hook")]
#[test]fn snapshot_child(){let Ok(root)=std::env::var("ATLAS_TEST_SNAPSHOT_CLOSED_ROOT") else{return};let d=Path::new(&root);let result=Vault::snapshot_closed(&d.join("source"),&d.join("copy"),"test-password",|_,_|{});std::env::remove_var("ATLAS_TEST_VAULT_OPEN_BARRIER_DIR");if result.is_ok(){let v=Vault::open(&d.join("copy"),"test-password").unwrap();assert_eq!(v.get_note("id").unwrap(),"OriginalBodyUnique48917","snapshot followed replacement");}else{let p=d.join("copy");if p.exists(){let bytes=fs::read(p).unwrap();assert!(!bytes.windows(23).any(|x|x==b"OriginalBodyUnique48917"));assert!(!bytes.windows(26).any(|x|x==b"ReplacementBodyUnique48917"));}}}
#[cfg(feature="test-hook")]
#[test]fn path_swap_after_fd_cannot_switch_source(){let d=temp();let src=d.join("source");let old=d.join("old");let replacement=d.join("replacement");let barrier=d.join("barrier");fs::create_dir(&barrier).unwrap();make(&src);fs::copy(&src,&replacement).unwrap();let mut v=Vault::open(&replacement,"test-password").unwrap();v.put_note("id","title","ReplacementBodyUnique48917").unwrap();drop(v);let mut child=Command::new(std::env::current_exe().unwrap()).args(["--exact","snapshot_child","--nocapture"]).env("ATLAS_TEST_SNAPSHOT_CLOSED_ROOT",&d).env("ATLAS_TEST_VAULT_OPEN_BARRIER_DIR",&barrier).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();let end=Instant::now()+Duration::from_secs(10);while !barrier.join("fd-ready").exists(){assert!(child.try_wait().unwrap().is_none(),"child exited before barrier");assert!(Instant::now()<end,"barrier timeout");thread::sleep(Duration::from_millis(10));}fs::rename(&src,&old).unwrap();fs::rename(&replacement,&src).unwrap();fs::write(barrier.join("fd-resume"),b"go").unwrap();let result=child.wait_with_output().unwrap();assert!(result.status.success(),"{}",String::from_utf8_lossy(&result.stderr));assert_eq!(Vault::open(&old,"test-password").unwrap().get_note("id").unwrap(),"OriginalBodyUnique48917");assert_eq!(Vault::open(&src,"test-password").unwrap().get_note("id").unwrap(),"ReplacementBodyUnique48917");fs::remove_dir_all(d).unwrap();}
